def multiscale_morph(img, num):
    img = np.array(img, dtype=np.float64)
    FM = np.zeros_like(img, dtype=np.float64)  # FM: Focus-measure
    for ii in range(1, num+1):
        scale = 2 * ii+1  # 2*(2 * ii + 1)-1
        # kernel = cv2.getStructuringElement(cv2.MORPH_ELLIPSE, (scale, scale))
        SE=np.array(kernels[2*scale-1],dtype=np.uint8).reshape(2*scale-1,2*scale-1)

        dilate = cv2.morphologyEx(img, cv2.MORPH_DILATE, SE)
        erode = cv2.morphologyEx(img, cv2.MORPH_ERODE, SE)
        g = dilate-erode
        # the composite focus-measure
        FM += g/scale
    return FM

def show_subPlots(mats,titles,r,c,Enb=True):
    if not Enb:
        return 
    fig, axs = plt.subplots(nrows=r, ncols=c, figsize=( c*4,r*4))
    for i in range(r):
        for j in range(c):   
            axs[i, j].imshow(mats[i*2+j], cmap='gray')
            axs[i, j].set_title(titles[i*2+j])
    plt.tight_layout() 
    plt.show()
    
def showImg(dat,title="",figsize=( 8,8)):
    plt.figure(figsize=figsize)
    plt.imshow(dat, cmap='gray')
    plt.title(title)
    plt.show()
    
    
    